*,
::after,
::before {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
[hidden] {
  display: none !important;
}
body,
html {
  width: 100%;
  height: 100%;
  overflow: hidden;
}
body {
  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  font-size: 13px;
  user-select: none;
  -webkit-user-select: none;
}
#v2-server-disconnect-alert {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  padding: 10px 0;
  background-color: var(--red);
  color: #fff;
  text-align: center;
  font-weight: 500;
  font-size: var(--font-14);
  z-index: 999999;
  box-shadow: 0 4px 12px var(--red-40);
  pointer-events: none;
}
#v2-initial-loader {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: var(--brand-loader-bg);
  clip-path: inset(var(--header-h) 0 0);
  isolation: isolate;
  transition:
    opacity 0.4s ease,
    visibility 0.4s ease;
}
#v2-initial-loader::before {
  position: absolute;
  width: min(720px, 76vw);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    var(--brand-loader-ambient),
    transparent 62%
  );
  content: "";
  opacity: 0;
  transform: scale(0.72);
  animation: brand-loader-ambient-breathe 4.2s cubic-bezier(0.22, 1, 0.36, 1)
    forwards;
}
.brand-loader {
  position: relative;
  z-index: 1;
  display: flex;
  width: min(760px, calc(100vw - clamp(32px, 8vw, 112px)));
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.brand-loader-stage {
  position: relative;
  display: grid;
  width: 100%;
  height: clamp(118px, 16vw, 190px);
  place-items: center;
}
.brand-loader-signature {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.brand-loader-signature {
  gap: clamp(16px, 2.2vw, 30px);
  opacity: 0;
  transform: translate3d(0, 20%, 0) scale(0.9);
  will-change: transform, opacity;
  animation:
    brand-loader-signature-in 1.04s 0.12s cubic-bezier(0.16, 1, 0.3, 1) forwards,
    brand-loader-signature-breathe 1.8s 1.16s ease-in-out infinite alternate;
}
.brand-loader-logo-shell {
  position: relative;
  flex: 0 0 auto;
