  padding: var(--space-6);
  cursor: var(--link-cursor);
  border-radius: var(--radius-4);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.6;
  transition:
    background 0.2s,
    opacity 0.2s;
  background: 0 0;
}
.cpd-item-delete:hover {
