}
@keyframes cpdDeleteShake {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-3px);
  }
  40% {
    transform: translateX(3px);
  }
  60% {
    transform: translateX(-2px);
  }
  80% {
    transform: translateX(2px);
  }
}
.cpd-confirm-panel {
  display: flex;
  gap: var(--space-6);
  align-items: center;
}
.cpd-confirm-btn {
