  padding: 8px 10px;
}
.cpd-new-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--indigo-20);
  border: 1px solid var(--indigo-35);
  color: var(--indigo-text);
  border-radius: 7px;
  padding: 8px 12px;
  font-size: 13px;
  cursor: var(--link-cursor);
  transition: background 0.15s;
}
.cpd-new-btn:hover {
  background: var(--indigo-35);
  color: var(--white);
}
.header {
  --header-left-limit: min(
    var(--header-left-coverage),
    max(
