  width: 28px;
  height: 28px;
  flex: 0 0 auto;
}
.logo-title {
  font-size: var(--font-18);
  font-weight: 700;
  color: var(--text-strong);
  letter-spacing: -0.02em;
}
.project-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
