  transition: background 0.2s;
}
#projectNameEl {
  display: none;
}
body.in-gallery #btnBackToGallery,
body.in-gallery #projectNameEl {
  display: none;
}
.project-name:hover {
  background: var(--white-06);
}
.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}
.canvas-version-badge {
