  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.btn-share:hover {
  background: var(--white-12);
  color: var(--text-primary);
}
.btn-icon {
  width: 30px;
  height: 30px;
  background: 0 0;
  border: none;
  color: var(--text-secondary);
