  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.btn-icon:hover {
  background: var(--white-08);
  color: var(--text-primary);
}
.add-menu {
  position: absolute;
  background: var(--bg);
  border: 1px solid var(--white-10);
  border-radius: 14px;
  width: 200px;
  padding: 8px;
  box-shadow: 0 10px 40px var(--black-60);
