  background-size: 22px 22px;
  cursor: var(--grab-cursor);
}
.canvas-wrapper::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse 80% 60% at 50% 50%,
    var(--blue-10) 0,
    transparent 70%
  );
  pointer-events: none;
  z-index: 0;
}
.canvas-wrapper:active {
  cursor: var(--grabbing-cursor);
}
.canvas {
  position: absolute;
  transform-origin: 0 0;
  will-change: transform;
}
.connections-svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 5;
  overflow: visible;
}
.node {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0;
  cursor: var(--pointer-cursor);
  z-index: 10;
}
.node.selected {
  z-index: 100;
}
.node.dragging {
  z-index: 200;
  cursor: var(--grabbing-cursor);
}
.node.selected .node-label {
  color: var(--white-80);
}
.node-card {
  background: var(--bg-node);
  border: 1.5px solid var(--border-node);
  border-radius: var(--node-r);
  width: 220px;
  min-width: 160px;
  min-height: 100px;
  position: relative;
  transition: border-color 0.2s;
}
.media-card {
  width: auto;
  min-width: 100px;
  max-width: none;
}
.media-card .node-img,
.media-card video {
  max-width: none;
  min-height: 100px;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}
.node.selected:not(.comment-note-node) .node-card {
  border-color: var(--blue);
  box-shadow:
    0 0 0 2px var(--blue-50),
    0 10px 40px var(--blue-30);
}
.node.selected:not(.comment-note-node) .node-card.media-card {
  border-color: transparent;
  box-shadow: none;
}
.node:not(.selected) .node-card:hover {
  border-color: var(--white-20);
}
.node-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: calc(var(--node-r) - 1.5px) calc(var(--node-r) - 1.5px) 0 0;
  overflow: hidden;
  transform: translateZ(0);
  backface-visibility: hidden;
}
.node-upload-hint {
  position: absolute;
  top: 10px;
  right: 10px;
  opacity: 0;
  transition: opacity 0.2s;
  z-index: 10;
}
.img-node-preview:hover .node-upload-hint,
.node-card:hover .node-upload-hint {
  opacity: 1;
}
.upload-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  background: var(--black-70);
  border: 1px solid var(--white-18);
  color: var(--white-90);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  cursor: var(--link-cursor);
  font-family: inherit;
  transition: all 0.2s;
}
.upload-btn:hover {
  background: var(--bg-panel-card);
}
.node-port {
  display: none;
}
.out-port {
  right: -5px;
  top: 50%;
  transform: translateY(-50%);
}
.in-port {
  left: -5px;
  top: 50%;
  transform: translateY(-50%);
  background: var(--green);
}
.text-card {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 260px;
  height: 260px;
  min-width: unset;
  border: 1px solid transparent;
  transition: border-color 0.2s;
  background: var(--bg);
  border-radius: 18px;
}
.text-card-content {
  font-size: 13px;
  line-height: 1.6;
  color: var(--white-70);
  outline: 0;
  cursor: var(--text-cursor);
  overflow-y: auto;
  max-height: 100%;
}
.node-group {
  --group-drag-handle-height: 32px;
  position: absolute;
  border: 1.5px solid var(--indigo-60);
  background: var(--indigo-05);
  border-radius: 14px;
  z-index: 2;
  pointer-events: auto;
  cursor: var(--grab-cursor);
  display: flex;
  flex-direction: column;
  opacity: 0.92;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease,
    opacity 0.2s ease;
}
.node-group:hover {
  border-color: var(--indigo-70);
  background: var(--indigo-08);
  opacity: 1;
}
.node-group.selected {
  background: var(--indigo-15);
  z-index: 3;
  opacity: 1;
}
.node-group.selected::after {
  content: "";
  position: absolute;
  top: -8px;
  left: -8px;
  right: -8px;
  bottom: -8px;
  border: 9px solid var(--current-group-color, var(--indigo-30));
  opacity: 0.8;
  border-radius: 22px;
  pointer-events: none;
  box-shadow: 0 0 35px var(--indigo-50);
}
.node-group-drag-handle {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: var(--group-drag-handle-height);
  box-sizing: border-box;
  border-bottom: 1px solid
    color-mix(
      in srgb,
      var(--current-group-color, var(--indigo)) 22%,
      transparent
    );
  border-radius: 12px 12px 0 0;
  background: color-mix(
    in srgb,
    var(--current-group-color, var(--indigo)) 10%,
    transparent
  );
  user-select: none;
  touch-action: none;
  z-index: 9;
  transition: background-color 0.16s ease;
}
.node-group-drag-handle:hover {
  background: color-mix(
    in srgb,
    var(--current-group-color, var(--indigo)) 18%,
    transparent
  );
}
.node-group.selected .node-group-drag-handle {
  background: color-mix(
    in srgb,
    var(--current-group-color, var(--indigo)) 18%,
    transparent
  );
}
.node-group.selected .node-group-drag-handle:hover {
  background: color-mix(
    in srgb,
    var(--current-group-color, var(--indigo)) 24%,
    transparent
  );
}
.node-group-title {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 4px;
  font-size: 23px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 2px 4px;
  white-space: nowrap;
  transition: all 0.2s;
  user-select: text;
  cursor: var(--text-cursor);
  transform-origin: bottom left;
  transform: scale(var(--zoom-inv, 1));
  z-index: 101;
}
.node-group:hover .node-group-title {
  color: var(--text-primary);
}
.node-group.selected .node-group-title {
  color: var(--white-80);
}
.node-group.highlight-contain {
  border-color: var(--indigo-60);
  background: var(--indigo-08);
  box-shadow: 0 0 30px var(--indigo-35);
}
.group-resizer {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 12px;
  height: 12px;
  cursor: var(--resize-nwse-cursor);
  z-index: 10;
  opacity: 0.4;
  transition: opacity 0.2s;
  background-image: linear-gradient(
    135deg,
    transparent 50%,
    var(--white-40) 50%,
    var(--white-40) 60%,
    transparent 60%,
    transparent 70%,
    var(--white-40) 70%
  );
}
.node-group:hover .group-resizer,
.v2-node:hover .group-resizer {
  opacity: 0.85;
}
.group-resizer:hover {
  opacity: 1;
  transform: scale(1.3);
}
.node-group.resizing {
  border-color: var(--white-40);
  cursor: var(--resize-nwse-cursor);
}
.group-toolbar {
  position: absolute;
  bottom: calc(100% + 36px);
  left: 50%;
  transform: translateX(-50%) scale(var(--zoom-inv, 1));
  display: none;
  align-items: center;
  gap: 4px;
  background: var(--canvas-floating-toolbar-bg);
  padding: 4px 8px;
  border-radius: var(--radius-12);
  border: 1px solid var(--stroke-default);
  box-shadow: var(--shadow-menu);
  z-index: 100;
  pointer-events: auto;
  transform-origin: bottom center;
}
.group-toolbar.group-toolbar--detached {
  bottom: auto;
  left: 0;
  top: 0;
  transform: translate(-50%, calc(-100% - 36px)) scale(var(--zoom-inv, 1));
  z-index: 230;
  pointer-events: none;
}
.group-toolbar.group-toolbar--detached.is-visible {
  display: none;
}
.group-toolbar.group-toolbar--detached.is-visible.is-drag-preview,
.group-toolbar.group-toolbar--detached.is-visible.is-interactive {
  display: flex;
