body.is-viewport-animating #v2-canvas .group-toolbar.group-toolbar--detached,
body.is-zooming #v2-canvas .group-toolbar.group-toolbar--detached {
  display: none;
}
.node-group.selected .group-toolbar {
  display: flex;
}
.gt-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  min-width: 34px;
  height: 34px;
  padding: 0;
  background: 0 0;
  border: none;
  border-radius: 8px;
