.global-tooltip {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 100010;
  box-sizing: border-box;
  max-width: min(360px, calc(100vw - 16px));
  padding: 6px 14px;
  border-radius: 8px;
  background: var(--tooltip-bg);
  color: var(--tooltip-text);
  box-shadow: var(--tooltip-shadow);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.45;
  text-align: left;
  white-space: pre-line;
  overflow-wrap: anywhere;
  pointer-events: none;
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity 0.12s ease,
    transform 0.12s ease;
}
.global-tooltip[hidden] {
  display: none;
}
.global-tooltip.is-visible {
  opacity: 1;
  transform: translateY(0);
}
.global-tooltip.is-placement-right {
  transform: translateX(-4px);
}
.global-tooltip.is-placement-right.is-visible {
  transform: translateX(0);
}
.global-tooltip.is-placement-left {
  transform: translateX(4px);
}
.global-tooltip.is-placement-left.is-visible {
  transform: translateX(0);
}
.global-tooltip.is-placement-bottom {
  transform: translateY(-4px);
}
.global-tooltip.is-placement-bottom.is-visible {
  transform: translateY(0);
}
.global-tooltip-arrow {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
}
.global-tooltip.is-placement-top .global-tooltip-arrow {
  bottom: -6px;
  transform: translateX(-50%);
  border-width: 6px 6px 0 6px;
  border-style: solid;
  border-color: var(--tooltip-bg) transparent transparent transparent;
}
.global-tooltip.is-placement-bottom .global-tooltip-arrow {
  top: -6px;
  transform: translateX(-50%);
  border-width: 0 6px 6px 6px;
  border-style: solid;
  border-color: transparent transparent var(--tooltip-bg) transparent;
}
.global-tooltip.is-placement-right .global-tooltip-arrow {
  left: -6px;
  transform: translateY(-50%);
  border-width: 6px 6px 6px 0;
  border-style: solid;
  border-color: transparent var(--tooltip-bg) transparent transparent;
}
.global-tooltip.is-placement-left .global-tooltip-arrow {
  right: -6px;
  transform: translateY(-50%);
  border-width: 6px 0 6px 6px;
  border-style: solid;
  border-color: transparent transparent transparent var(--tooltip-bg);
}
@keyframes tooltipRightFadeIn {
  from {
    opacity: 0;
    transform: translateY(-50%) translateX(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(-50%) translateX(0);
  }
}
