  --text-cursor:
    url("../images/cursors/windows11-concept-v2/light/beam-small.cur"), text;
  --precision-cursor:
    url("../images/cursors/windows11-concept-v2/light/precision-small.cur"),
    crosshair;
  --move-cursor:
    url("../images/cursors/windows11-concept-v2/light/move-small.cur"), move;
  --wait-cursor:
    url("../images/cursors/windows11-concept-v2/light/busy.ani"), wait;
