  --help-cursor:
    url("../images/cursors/windows11-concept-v2/light/help-small.cur"), help;
  --unavailable-cursor:
    url("../images/cursors/windows11-concept-v2/light/unavailable-small.cur"),
    not-allowed;
  --resize-ns-cursor:
    url("../images/cursors/windows11-concept-v2/light/vert-small.cur"),
    ns-resize;
  --resize-ew-cursor:
    url("../images/cursors/windows11-concept-v2/light/horz-small.cur"),
    ew-resize;
  --resize-nwse-cursor:
    url("../images/cursors/windows11-concept-v2/light/dgn1-small.cur"),
    nwse-resize;
  --resize-nesw-cursor:
    url("../images/cursors/windows11-concept-v2/light/dgn2-small.cur"),
    nesw-resize;
  --alternate-cursor:
    url("../images/cursors/windows11-concept-v2/light/alternate-small.cur"),
    default;
  --handwriting-cursor:
    url("../images/cursors/windows11-concept-v2/light/handwriting-small.cur"),
    default;
  --pin-cursor:
    url("../images/cursors/windows11-concept-v2/light/pin-small.cur"), pointer;
  --person-cursor:
    url("../images/cursors/windows11-concept-v2/light/person-small.cur"),
