.mascot-wrap {
  position: fixed;
  right: 88px;
  bottom: 18px;
  z-index: 510;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  pointer-events: none;
  opacity: 0;
  transform: translateY(30px) scale(0.8);
  transition:
    opacity 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.mascot-wrap.visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}
.mascot-bubble {
  position: relative;
  background: var(--about-dialog-bg);
  border: 1px solid var(--indigo-45);
  border-radius: var(--radius-14);
  padding: var(--space-10) var(--space-14);
  max-width: 210px;
  min-width: 130px;
  box-shadow: var(--shadow-mascot);
  backdrop-filter: blur(var(--blur-mascot));
  margin-bottom: var(--space-6);
}
.mascot-bubble-text {
  font-size: var(--font-13);
  line-height: 1.6;
  color: var(--text-strong);
  font-family: inherit;
  white-space: pre-wrap;
  word-break: break-word;
}
.mascot-bubble-tail {
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-top: 8px solid var(--indigo-45);
}
.mascot-bubble-tail::after {
  content: "";
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-top: 7px solid var(--about-dialog-bg);
}
.mascot-figure {
