  max-height: min(88vh, 760px);
  overflow-y: auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  padding: var(--space-20);
  border-radius: var(--radius-16);
  border: 1px solid var(--stroke-default);
