.settings-input-with-hint {
  position: relative;
  display: flex;
  align-items: center;
}
.settings-hint-icon {
  position: absolute;
  right: 12px;
  color: var(--text-muted);
  cursor: var(--help-cursor);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--bg-2);
  border: 1px solid var(--stroke-10);
  transition: all 0.2s ease;
}
.settings-hint-icon:hover {
  background: var(--bg-3);
  color: var(--text-primary);
  border-color: var(--stroke-20);
}
.settings-hint-icon svg {
  width: 12px;
  height: 12px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
}
.settings-input-with-hint .settings-input {
  padding-right: 36px;
}
.settings-hint-icon--inline {
  position: relative;
  width: 24px;
  height: 24px;
  margin-left: var(--space-6);
  flex-shrink: 0;
  color: var(--warning-text);
  cursor: var(--help-cursor);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: 0 0;
  border: none;
  padding: 0;
}
.settings-hint-icon--inline svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  stroke-width: 1.5;
}
.settings-hint-tooltip {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.15s ease,
    visibility 0.15s ease;
  pointer-events: none;
}
.settings-hint-icon--inline:focus-visible .settings-hint-tooltip,
.settings-hint-icon--inline:hover .settings-hint-tooltip {
  opacity: 1;
  visibility: visible;
}
.settings-hint-icon--inline:focus-visible {
  outline: 2px solid var(--warning-border);
  outline-offset: 2px;
}
.settings-hint-tooltip-content {
  background: var(--tooltip-bg);
  color: var(--tooltip-text);
  font-size: var(--font-12);
  padding: 10px 14px;
  border-radius: 8px;
  box-shadow: var(--tooltip-shadow);
  font-weight: 500;
  line-height: 1.6;
  min-width: 320px;
  max-width: 400px;
  text-align: left;
  white-space: normal;
}
.settings-hint-tooltip-title {
  margin-bottom: var(--space-6);
  font-weight: 700;
  color: var(--tooltip-text);
}
.settings-hint-tooltip-list {
  margin: 0;
  padding-left: var(--space-18);
}
.settings-hint-tooltip-list li + li {
  margin-top: var(--space-6);
}
.settings-hint-tooltip-content .curl-highlight {
  color: var(--error-text);
  font-weight: 600;
}
.settings-hint-tooltip-arrow {
  position: absolute;
