}
.v2-workflow-card-delete {
  right: var(--space-6);
  width: 28px;
}
.v2-workflow-card:focus-within .v2-workflow-card-delete,
.v2-workflow-card:focus-within .v2-workflow-card-load,
.v2-workflow-card:hover .v2-workflow-card-delete,
.v2-workflow-card:hover .v2-workflow-card-load {
  opacity: 1;
  pointer-events: auto;
}
.v2-workflow-card-load:hover {
  background: var(--fill-active);
  border-color: var(--blue-border-focus);
  transform: scale(1.03);
}
.v2-workflow-card-load:active {
  transform: scale(0.97);
}
.v2-workflow-card-load:disabled {
  cursor: var(--wait-cursor);
}
.v2-workflow-card-load svg {
  width: 14px;
  height: 14px;
  display: block;
}
.v2-workflow-card-delete:hover {
  background: var(--fill-danger-soft);
  border-color: var(--stroke-danger);
  color: var(--red);
  transform: scale(1.03);
}
.v2-workflow-card-delete:active {
  transform: scale(0.97);
}
.v2-workflow-card-delete svg {
  width: 14px;
  height: 14px;
  display: block;
}
.v2-workflow-note-hint {
