  border-radius: var(--radius-7);
  background: var(--surface-float);
  color: var(--text-primary);
  box-shadow: var(--shadow-menu);
  font-size: var(--font-12);
  font-weight: 400;
  line-height: 1.45;
  text-align: left;
  white-space: pre-wrap;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translateY(2px);
  transition:
    opacity 0.14s,
    transform 0.14s;
  z-index: 20;
}
.v2-workflow-note-hint:focus-visible::after,
.v2-workflow-note-hint:hover::after {
  opacity: 1;
  transform: translateY(0);
}
.v2-workflow-card-delete-confirm {
