}
.panorama-camera-timeline {
  position: absolute;
  left: 50%;
  bottom: 72px;
  width: min(760px, calc(100% - 32px));
  min-height: 48px;
  transform: translateX(-50%);
  padding: var(--space-8);
  border: 1px solid var(--panorama-scene-current-toolbar-border);
  border-radius: var(--radius-8);
  background: var(--panorama-scene-current-menu-bg);
  color: var(--panorama-scene-current-toolbar-fg);
  box-shadow: var(--panorama-scene-current-toolbar-shadow);
  display: grid;
  grid-template-columns: 32px 32px 56px minmax(140px, 1fr) 64px 76px auto;
  align-items: center;
  gap: var(--space-6);
  box-sizing: border-box;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.16s ease;
}
.panorama-camera-timeline.is-visible {
  opacity: 1;
  pointer-events: auto;
}
.panorama-scene-component.has-camera-timeline
