  transform: translateY(-72px);
}
.panorama-camera-timeline__icon {
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--radius-6);
  background: 0 0;
  color: currentColor;
  font-size: var(--font-14);
}
.panorama-camera-timeline__icon:focus-visible,
.panorama-camera-timeline__icon:hover {
  background: var(--white-06);
  outline: 1px solid var(--blue-40);
}
.panorama-camera-timeline__time {
  font-size: var(--font-11);
  font-variant-numeric: tabular-nums;
}
.panorama-camera-timeline__track-wrap {
  position: relative;
  min-width: 0;
  min-height: 34px;
  padding-bottom: 14px;
  box-sizing: border-box;
}
.panorama-camera-timeline__track {
  width: 100%;
  margin: 0;
}
.panorama-camera-timeline__markers {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 1px;
  height: 12px;
  pointer-events: none;
}
.panorama-camera-timeline__marker {
  position: absolute;
  left: var(--panorama-keyframe-position, 0);
  width: 10px;
  height: 10px;
  padding: 0;
  border: 1px solid var(--panorama-scene-current-toolbar-fg);
  border-radius: 2px;
  background: var(--blue-20);
  color: currentColor;
  transform: translateX(-50%) rotate(45deg);
  pointer-events: auto;
}
.panorama-camera-timeline__marker.is-current,
.panorama-camera-timeline__marker:focus-visible,
.panorama-camera-timeline__marker:hover {
  background: var(--blue-40);
  outline: 0;
}
.panorama-camera-timeline__duration {
  width: 64px;
}
.panorama-camera-timeline__loop {
  display: inline-flex;
  align-items: center;
  gap: var(--space-4);
  font-size: var(--font-11);
  white-space: nowrap;
}
@media (max-width: 760px) {
  .panorama-asset-browser__results {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .panorama-camera-timeline {
    grid-template-columns: 32px 32px 52px minmax(100px, 1fr);
  }
  .panorama-camera-timeline__duration,
  .panorama-camera-timeline__fps,
  .panorama-camera-timeline__loop {
    display: none;
  }
}
