.storyboard-3d-home-generation-error {
  margin: 0 14px 12px;
  color: var(--error-text);
  font-size: var(--font-11);
  line-height: 1.5;
}
.storyboard-3d-model-pack-backdrop {
  position: fixed;
  inset: var(--header-h) 0 0;
  z-index: 30;
  display: grid;
  place-items: center;
  padding: clamp(16px, 4vw, 48px);
  background: color-mix(in srgb, var(--bg) 72%, transparent);
  backdrop-filter: blur(8px);
}
.storyboard-3d-model-pack-dialog {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: clamp(16px, 2.4vw, 26px);
  width: min(560px, calc(100vw - 32px));
  max-height: min(560px, calc(100vh - var(--header-h) - 32px));
  padding: clamp(20px, 3vw, 30px);
  overflow: auto;
  border: 1px solid var(--storyboard-3d-home-accent-border-soft);
  border-radius: clamp(18px, 2vw, 26px);
  color: var(--text-primary);
  background: var(--surface-float);
  box-shadow: var(--shadow-dialog);
}
.storyboard-3d-model-pack-mark {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  border: 1px solid var(--storyboard-3d-home-accent-border-soft);
  border-radius: 20px;
  color: var(--storyboard-3d-home-accent-text);
  background: var(--storyboard-3d-home-accent-soft);
}
.storyboard-3d-model-pack-mark svg {
  width: 38px;
  height: 38px;
