  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.4;
}
.storyboard-3d-model-pack-dialog h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--font-20);
}
.storyboard-3d-model-pack-dialog p {
  margin: 10px 0 0;
  color: var(--text-secondary);
  font-size: var(--font-13);
  line-height: 1.7;
}
.storyboard-3d-model-pack-progress {
  display: grid;
  gap: 8px;
  margin-top: 16px;
  padding: 12px 14px;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-12);
  background: var(--surface-panel);
}
.storyboard-3d-model-pack-progress-heading,
.storyboard-3d-model-pack-progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.storyboard-3d-model-pack-progress-heading strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: var(--font-12);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-model-pack-progress-heading span {
  color: var(--storyboard-3d-home-accent-text);
  font-size: var(--font-12);
  font-variant-numeric: tabular-nums;
  font-weight: 750;
}
.storyboard-3d-model-pack-progress progress {
  width: 100%;
  height: 8px;
  overflow: hidden;
  border: 0;
  border-radius: 999px;
  appearance: none;
  background: var(--stroke-default);
}
.storyboard-3d-model-pack-progress progress::-webkit-progress-bar {
  border-radius: inherit;
  background: var(--stroke-default);
}
.storyboard-3d-model-pack-progress progress::-webkit-progress-value {
  border-radius: inherit;
  background: var(--storyboard-3d-home-accent);
  transition: width 180ms ease;
}
.storyboard-3d-model-pack-progress progress::-moz-progress-bar {
  border-radius: inherit;
  background: var(--storyboard-3d-home-accent);
  transition: width 180ms ease;
}
.storyboard-3d-model-pack-progress-meta,
.storyboard-3d-model-pack-progress > small {
  color: var(--text-muted);
  font-size: var(--font-11);
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-model-pack-progress > small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-model-pack-error {
  display: block;
  margin-top: 10px;
  color: var(--error-text);
  line-height: 1.5;
}
.storyboard-3d-model-pack-dialog footer {
  display: flex;
  grid-column: 1/-1;
  justify-content: flex-end;
  gap: 10px;
}
.storyboard-3d-model-pack-dialog
  footer
  > button:not(.storyboard-3d-home-primary) {
  min-height: 42px;
  padding: 9px 16px;
  border: 1px solid var(--stroke-default);
  border-radius: 999px;
  color: var(--text-secondary);
  background: var(--surface-panel);
  cursor: var(--link-cursor);
}
.storyboard-3d-model-pack-dialog button:disabled {
  cursor: var(--unavailable-cursor);
  opacity: 0.5;
}
.storyboard-3d-home-projects {
  margin-top: clamp(24px, 3.6dvh, 38px);
}
.storyboard-3d-home-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
}
.storyboard-3d-home-section-heading h2 {
  margin: 0;
  color: var(--text-strong);
  font-family: STSong, "Songti SC", serif;
  font-size: var(--font-24);
  font-weight: 600;
}
.storyboard-3d-home-search {
  display: flex;
  align-items: center;
  gap: 8px;
  width: min(260px, 34vw);
  min-height: 38px;
  padding: 7px 11px;
  border: 1px solid var(--stroke-default);
  border-radius: 999px;
  color: var(--text-muted);
  background: var(--surface-panel);
}
.storyboard-3d-home-search:focus-within {
  border-color: color-mix(in srgb, var(--cyan) 62%, var(--stroke-default));
}
.storyboard-3d-home-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  color: var(--text-primary);
  background: 0 0;
  font: inherit;
  font-size: var(--font-12);
}
.storyboard-3d-home-project-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr));
  gap: 16px;
  margin-top: 12px;
}
.storyboard-3d-home-create-card,
.storyboard-3d-home-project-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--stroke-default);
  border-radius: 22px;
  color: var(--text-primary);
  background: var(--bg-panel-card);
  text-align: left;
  cursor: var(--link-cursor);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}
.storyboard-3d-home-project-card {
  position: relative;
  display: grid;
  grid-template-rows: minmax(150px, 19vh) auto;
  padding: 0;
  cursor: default;
}
.storyboard-3d-home-create-card:hover,
.storyboard-3d-home-project-card:hover {
  border-color: color-mix(in srgb, var(--cyan) 42%, var(--stroke-default));
  transform: translateY(-3px);
  box-shadow: var(--shadow-surface);
}
.storyboard-3d-home-project-card.is-delete-confirming {
  border-color: color-mix(
    in srgb,
    var(--stroke-danger) 70%,
    var(--stroke-default)
  );
}
.storyboard-3d-home-project-preview {
  position: relative;
  display: block;
  width: 100%;
  min-height: 150px;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-bottom: 1px solid var(--stroke-default);
  background: var(--surface-panel);
  color: inherit;
  cursor: var(--link-cursor);
}
.storyboard-3d-home-project-preview > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.storyboard-3d-home-project-placeholder {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: var(--cyan);
  background: var(--surface-panel);
}
.storyboard-3d-home-grid-plane {
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 120%;
  height: 75%;
  background-image:
    linear-gradient(
      color-mix(in srgb, var(--cyan) 16%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--cyan) 16%, transparent) 1px,
      transparent 1px
    );
  background-size: 24px 24px;
  transform: perspective(260px) rotateX(62deg);
  transform-origin: center bottom;
}
.storyboard-3d-home-placeholder-icon {
  position: relative;
  width: 54px;
  height: 54px;
}
.storyboard-3d-home-project-placeholder small {
  position: absolute;
  right: 12px;
  bottom: 10px;
  max-width: calc(100% - 24px);
  overflow: hidden;
  color: var(--text-muted);
  font-size: var(--font-11);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-home-project-status {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--cyan) 42%, transparent);
  border-radius: 999px;
  color: var(--cyan);
  background: color-mix(in srgb, var(--bg-panel-card) 86%, transparent);
  font-size: var(--font-11);
}
.storyboard-3d-home-project-more {
  position: absolute;
  z-index: 3;
  top: 12px;
  right: 12px;
