  place-items: center;
  border: 1px solid color-mix(in srgb, var(--text-primary) 20%, transparent);
  border-radius: 999px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--bg-panel-card) 86%, transparent);
  backdrop-filter: blur(10px);
  cursor: var(--link-cursor);
}
.storyboard-3d-home-project-card.is-menu-open .storyboard-3d-home-project-more,
.storyboard-3d-home-project-more:focus-visible,
.storyboard-3d-home-project-more:hover {
  border-color: color-mix(in srgb, var(--cyan) 55%, var(--stroke-default));
  color: var(--cyan);
  outline: 0;
}
.storyboard-3d-home-project-more > span {
  transform: translateY(-2px);
  font-size: var(--font-13);
  letter-spacing: 1px;
}
.storyboard-3d-home-project-menu {
  position: absolute;
  z-index: 4;
  top: 50px;
  right: 12px;
