}
.storyboard-3d-home-project-menu[hidden] {
  display: none;
}
.storyboard-3d-home-project-menu button {
  min-height: 36px;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--radius-8);
  color: var(--text-primary);
  background: 0 0;
  font: inherit;
  font-size: var(--font-12);
  text-align: left;
  cursor: var(--link-cursor);
}
.storyboard-3d-home-project-menu button:focus-visible,
.storyboard-3d-home-project-menu button:hover {
  outline: 0;
  background: var(--fill-hover-strong);
}
.storyboard-3d-home-project-menu button.is-danger {
  color: var(--text-danger);
}
.storyboard-3d-home-project-delete-confirm {
  position: absolute;
  z-index: 4;
  top: 12px;
  right: 12px;
