  align-items: center;
  justify-content: flex-end;
  gap: var(--space-4);
  padding: 4px;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  background: color-mix(in srgb, var(--bg-panel-card) 90%, transparent);
  box-shadow: var(--shadow-popover);
  backdrop-filter: blur(10px);
}
.storyboard-3d-home-project-delete-confirm-button {
  min-width: 48px;
  min-height: 30px;
  padding: 5px 10px;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-7);
  color: var(--text-primary);
  background: var(--fill-hover-strong);
  font: inherit;
  font-size: var(--font-12);
  font-weight: 500;
  cursor: var(--link-cursor);
}
.storyboard-3d-home-project-delete-confirm-button:focus-visible,
.storyboard-3d-home-project-delete-confirm-button:hover {
  outline: 0;
  background: var(--fill-active);
}
.storyboard-3d-home-project-delete-confirm-button.is-danger {
  border-color: var(--stroke-danger);
  color: var(--text-on-danger);
  background: var(--btn-danger-bg);
}
.storyboard-3d-home-project-delete-confirm-button.is-danger:focus-visible,
.storyboard-3d-home-project-delete-confirm-button.is-danger:hover {
  background: var(--btn-danger-bg-hover);
}
.storyboard-3d-home-project-copy {
  display: grid;
  align-content: start;
  gap: 5px;
  padding: 16px;
}
.storyboard-3d-home-project-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 10px;
}
.storyboard-3d-home-project-details,
.storyboard-3d-home-project-title {
  min-width: 0;
  padding: 0;
  border: 0;
  color: inherit;
  background: 0 0;
  font: inherit;
  text-align: left;
  cursor: var(--link-cursor);
}
.storyboard-3d-home-project-title {
  display: block;
  overflow: hidden;
}
.storyboard-3d-home-project-title:focus-visible strong,
.storyboard-3d-home-project-title:hover strong {
  color: var(--cyan);
}
.storyboard-3d-home-project-details:focus-visible,
.storyboard-3d-home-project-title:focus-visible {
  outline: 1px solid color-mix(in srgb, var(--cyan) 65%, transparent);
  outline-offset: 3px;
}
.storyboard-3d-home-project-heading input {
  width: 100%;
  min-width: 0;
  height: 30px;
  padding: 4px 7px;
  border: 1px solid color-mix(in srgb, var(--cyan) 64%, var(--stroke-default));
  border-radius: var(--radius-8);
  outline: 0;
  color: var(--text-strong);
  background: var(--surface-panel);
  font: inherit;
  font-size: var(--font-15);
}
.storyboard-3d-home-project-heading strong {
  overflow: hidden;
  color: var(--text-strong);
  font-size: var(--font-15);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-home-project-heading small,
.storyboard-3d-home-project-scene {
  overflow: hidden;
  color: var(--text-muted);
  font-size: var(--font-11);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-home-project-details {
  display: grid;
  gap: 5px;
}
.storyboard-3d-home-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.storyboard-3d-home-project-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--stroke-default);
}
.storyboard-3d-home-project-stats > span {
  display: grid;
  gap: 2px;
  color: var(--text-muted);
  font-size: var(--font-11);
}
.storyboard-3d-home-project-stats b {
  color: var(--text-primary);
  font-size: var(--font-13);
}
.storyboard-3d-home-create-card {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  min-height: clamp(92px, 11dvh, 124px);
  border-style: dashed;
  color: var(--text-secondary);
  text-align: center;
}
.storyboard-3d-home-create-card > span {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--stroke-default);
  border-radius: 50%;
  color: var(--cyan);
  background: var(--surface-panel);
  font-size: var(--font-24);
  font-weight: 300;
}
.storyboard-3d-home-create-card strong {
  color: var(--text-primary);
  font-size: var(--font-13);
}
.storyboard-3d-home-create-card small {
  color: var(--text-muted);
  font-size: var(--font-11);
}
.storyboard-3d-home-empty-projects,
.storyboard-3d-home-search-empty {
  display: grid;
  justify-items: center;
  gap: 9px;
  margin-top: 14px;
  padding: clamp(36px, 7vh, 72px) 24px;
  border: 1px dashed var(--stroke-default);
  border-radius: 20px;
  color: var(--text-secondary);
  background: var(--bg-panel-card);
  text-align: center;
}
.storyboard-3d-home-empty-projects > div {
  display: grid;
  place-items: center;
  width: 60px;
  height: 60px;
  margin-bottom: 4px;
  border: 1px solid var(--stroke-default);
  border-radius: 16px;
  color: var(--cyan);
  background: var(--surface-panel);
}
.storyboard-3d-home-empty-icon {
  width: 34px;
  height: 34px;
}
.storyboard-3d-home-empty-projects > strong,
.storyboard-3d-home-search-empty > strong {
  color: var(--text-strong);
  font-size: var(--font-15);
}
.storyboard-3d-home-empty-projects > span,
.storyboard-3d-home-search-empty > span {
  color: var(--text-muted);
  font-size: var(--font-12);
}
.storyboard-3d-home-empty-projects .storyboard-3d-home-primary {
  margin-top: 8px;
}
.storyboard-3d-home-search-empty[hidden] {
  display: none;
}
.storyboard-3d-home-project-card[hidden] {
  display: none;
}
@media (max-width: 640px) {
  .storyboard-3d-workspace-home-page {
    width: calc(100vw - 24px);
  }
  .storyboard-3d-home-section-heading {
    align-items: stretch;
    flex-direction: column;
    gap: 14px;
  }
  .storyboard-3d-home-search {
    width: 100%;
  }
  .storyboard-3d-home-model-bar .img-model-btn-trigger {
    max-width: min(260px, 58vw);
  }
}
@media (max-width: 480px) {
  .storyboard-3d-home-model-bar {
    align-items: stretch;
    flex-direction: column;
  }
  .storyboard-3d-home-generate,
  .storyboard-3d-home-model-bar .aigen-text-model-selector,
  .storyboard-3d-home-model-bar .img-model-btn-trigger,
  .storyboard-3d-home-model-bar .img-model-wrap {
    width: 100%;
    max-width: none;
  }
  .storyboard-3d-home-composer-actions {
    width: 100%;
  }
  .storyboard-3d-home-composer-actions .storyboard-3d-home-generate,
  .storyboard-3d-home-reference-button {
    flex: 1 1 0;
  }
  .storyboard-3d-model-pack-dialog {
    grid-template-columns: 1fr;
  }
  .storyboard-3d-model-pack-dialog footer {
    grid-column: 1;
    flex-direction: column-reverse;
  }
  .storyboard-3d-model-pack-dialog footer > button {
    width: 100%;
  }
}
.storyboard-3d-editor-overlay {
  --storyboard-3d-editor-top-offset: 0px;
  position: fixed;
  inset: max(var(--header-h), var(--storyboard-3d-editor-top-offset, 0px)) 0 0;
  z-index: 12000;
  width: 100vw;
  height: auto;
  overflow: hidden;
  color: var(--text-primary);
  background: var(--bg);
}
.storyboard-3d-editor-shell {
  position: relative;
  display: grid;
  grid-template-rows: clamp(48px, 5.4vh, 56px) minmax(0, 1fr);
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.storyboard-3d-editor-topbar {
  z-index: 9;
  min-width: 0;
  padding: 0 clamp(10px, 1.2vw, 18px);
