  gap: 1px;
  min-width: 120px;
  max-width: min(32vw, 420px);
}
.storyboard-3d-editor-identity input {
  width: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--text-strong);
  background: 0 0;
  font: inherit;
  font-size: 14px;
  font-weight: 700;
