.storyboard-3d-asset-toolbar small {
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.5;
}
.storyboard-3d-asset-toolbar [data-storyboard-3d-import-status]:not(:empty) {
  padding: var(--space-4) var(--space-6);
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-6);
  color: var(--text-secondary);
  background: var(--bg-panel-card);
  text-align: center;
}
.storyboard-3d-asset-filters {
  display: flex;
  min-height: 0;
  gap: var(--space-16);
  flex: 1 1 auto;
  flex-direction: column;
}
.storyboard-3d-asset-filters label {
  display: grid;
  gap: var(--space-8);
}
.storyboard-3d-asset-filters input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-6);
  color: var(--text-primary);
  background: var(--bg-panel-card);
  font: inherit;
  font-size: 12px;
}
.storyboard-3d-asset-category-panel {
  display: flex;
  min-height: 0;
  gap: var(--space-8);
  flex: 1 1 auto;
  flex-direction: column;
}
.storyboard-3d-asset-category-panel > span {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}
.storyboard-3d-asset-category-list {
  display: grid;
  min-height: 0;
  gap: var(--space-2);
  padding-right: var(--space-4);
  overflow-y: auto;
  align-content: start;
}
.storyboard-3d-asset-category-list button {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  min-height: 30px;
  padding-inline: var(--space-12);
  border-color: transparent;
  color: var(--text-secondary);
  background: 0 0;
  text-align: left;
}
.storyboard-3d-asset-category-list button:hover:not(:disabled) {
  border-color: transparent;
  color: var(--text-primary);
  background: var(--fill-hover);
}
.storyboard-3d-asset-category-list button.is-active {
  border-color: var(--blue-25);
  color: var(--blue);
  background: var(--blue-10);
  box-shadow: inset 2px 0 0 var(--blue);
}
.storyboard-3d-asset-category-list button:focus-visible {
  outline: 2px solid var(--blue-border-focus);
  outline-offset: -2px;
}
.storyboard-3d-asset-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(180px, 100%), 1fr));
  gap: var(--space-12);
  min-height: 0;
  padding-right: var(--space-6);
  align-content: start;
  overflow-y: auto;
}
.storyboard-3d-asset-results {
  display: grid;
  height: 100%;
  min-height: 0;
  grid-template-rows: minmax(0, 1fr) auto;
}
.storyboard-3d-asset-grid article {
  position: relative;
  min-width: 0;
}
.storyboard-3d-asset-grid article > [data-storyboard-3d-action="add-asset"] {
  width: 100%;
  height: 100%;
  padding: var(--space-10);
  border-color: var(--stroke-weak);
  background: var(--bg-panel-card);
}
.storyboard-3d-asset-grid .storyboard-3d-asset-favorite {
  position: absolute;
  top: 8px;
  right: 8px;
  display: inline-grid;
  width: 28px;
  min-height: 28px;
  padding: 0;
  place-items: center;
  color: var(--text-muted);
  background: 0 0;
}
.storyboard-3d-asset-grid .storyboard-3d-asset-favorite.is-active {
  color: var(--gold);
}
.storyboard-3d-asset-grid button {
  display: grid;
  gap: var(--space-6);
  min-width: 0;
  padding: var(--space-8);
  text-align: left;
}
.storyboard-3d-asset-grid button span,
.storyboard-3d-asset-grid button strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-asset-grid button span {
  color: var(--blue);
  font-size: 10px;
  text-transform: uppercase;
}
.storyboard-3d-asset-grid button strong {
  color: var(--text-primary);
  font-size: 12px;
}
.storyboard-3d-asset-grid button .storyboard-3d-asset-thumb {
  display: grid;
  width: 100%;
  height: clamp(112px, 16vh, 160px);
  overflow: hidden;
  place-items: center;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-10);
  color: var(--text-muted);
  background: var(--surface-panel);
}
.storyboard-3d-asset-thumb img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.storyboard-3d-asset-grid button .storyboard-3d-asset-thumb-loading {
  display: grid;
  gap: var(--space-8);
  place-items: center;
  color: var(--text-muted);
  text-transform: none;
}
.storyboard-3d-asset-thumb-loading i {
  width: 34px;
  height: 34px;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-8);
  background: var(--bg-panel-card);
  animation: storyboard-3d-asset-thumb-pulse 1.2s ease-in-out infinite;
}
.storyboard-3d-asset-thumb[data-thumbnail-status="loading"]
  .storyboard-3d-asset-thumb-loading
  i {
  border-color: var(--blue-30);
}
@keyframes storyboard-3d-asset-thumb-pulse {
  50% {
    opacity: 0.42;
    transform: scale(0.94);
  }
}
.storyboard-3d-assets-load-more {
  width: 100%;
  margin-top: var(--space-8);
  color: var(--text-secondary);
  background: var(--bg-panel-card);
}
.storyboard-3d-viewport-column {
  --storyboard-3d-timeline-height: min(340px, calc(100% - 160px));
  display: grid;
  grid-template-rows: minmax(0, 1fr) clamp(132px, 18vh, 180px);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--bg-2);
  transition: grid-template-rows 240ms cubic-bezier(0.22, 1, 0.36, 1);
}
.storyboard-3d-viewport-column.is-timeline-open {
  grid-template-rows: minmax(160px, 1fr) minmax(
      0,
      var(--storyboard-3d-timeline-height)
    );
}
body.storyboard-3d-timeline-resizing {
  cursor: ns-resize;
  user-select: none;
}
body.storyboard-3d-timeline-resizing .storyboard-3d-viewport-column {
  transition: none;
}
.storyboard-3d-viewport {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  outline: 0;
  background: var(--panorama-scene-viewport-night-bg);
}
.storyboard-3d-viewport::before {
  position: absolute;
  inset: 0;
  content: "";
  background: var(--panorama-scene-viewport-night-overlay);
  opacity: 0.65;
}
.storyboard-3d-viewport-stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  color: var(--text-secondary);
  background: var(--panorama-scene-viewport-night-bg);
}
.storyboard-3d-runtime-host {
  position: absolute;
  inset: 0;
  touch-action: none;
}
.storyboard-3d-background-calibration-guide {
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: hidden;
  pointer-events: none;
}
.storyboard-3d-background-calibration-guide svg {
  display: block;
  width: 100%;
  height: 100%;
}
.storyboard-3d-background-horizon-hit {
  stroke: transparent;
  stroke-width: 28;
  pointer-events: stroke;
  cursor: ns-resize;
  touch-action: none;
}
.storyboard-3d-background-vanishing-point-hit {
  fill: transparent;
  stroke: transparent;
  stroke-width: 8;
  pointer-events: all;
  cursor: move;
  touch-action: none;
}
.storyboard-3d-background-calibration-guide.is-adjusting
  .storyboard-3d-background-horizon,
.storyboard-3d-background-calibration-guide:has(
    .storyboard-3d-background-horizon-hit:hover
  )
  .storyboard-3d-background-horizon {
  stroke-width: 3;
}
.storyboard-3d-background-vanishing-point-hit:hover {
  fill: var(--cyan-05);
  stroke: var(--cyan-60);
}
.storyboard-3d-background-calibration-guide.is-adjusting
  .storyboard-3d-background-vanishing-point {
  stroke-width: 3;
}
.storyboard-3d-background-ground-region {
  fill: var(--cyan-05);
  stroke: var(--cyan-30);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.storyboard-3d-background-horizon {
  stroke: var(--cyan-text);
  stroke-width: 2;
  stroke-dasharray: 8 5;
  vector-effect: non-scaling-stroke;
}
.storyboard-3d-background-axis {
  stroke: var(--cyan-60);
  stroke-width: 1;
  stroke-dasharray: 4 6;
  vector-effect: non-scaling-stroke;
}
.storyboard-3d-background-vanishing-point {
  fill: var(--warning-text);
  stroke: var(--surface-panel);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}
.storyboard-3d-background-calibration-guide span {
  position: absolute;
  top: clamp(54px, 8vh, 82px);
  left: 50%;
  max-width: min(360px, calc(100% - 144px));
  padding: var(--space-4) var(--space-10);
  border: 1px solid var(--cyan-30);
  border-radius: var(--radius-999);
  color: var(--cyan-text);
  background: color-mix(in srgb, var(--surface-panel) 78%, transparent);
  font-size: 11px;
  white-space: nowrap;
  transform: translateX(-50%);
}
.storyboard-3d-runtime-host.is-box-selecting {
  cursor: crosshair;
}
.storyboard-3d-selection-box {
  position: absolute;
  z-index: 4;
  box-sizing: border-box;
  border: 1px solid var(--blue-border-strong);
  background: var(--blue-10);
  pointer-events: none;
}
.storyboard-3d-runtime-host.is-gizmo-hovered {
  cursor: var(--grab-cursor);
}
.storyboard-3d-runtime-host.is-gizmo-dragging {
  cursor: var(--grabbing-cursor);
}
.storyboard-3d-runtime-host.is-camera-dolly,
.storyboard-3d-runtime-host.is-camera-fly-look,
.storyboard-3d-runtime-host.is-camera-orbit,
.storyboard-3d-runtime-host.is-camera-pan {
  cursor: var(--grabbing-cursor);
}
.storyboard-3d-runtime-host canvas {
  display: block;
  width: 100%;
  height: 100%;
  outline: 0;
}
.storyboard-3d-runtime-status {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 3;
  max-width: min(520px, calc(100% - 48px));
  padding: var(--space-12) var(--space-16);
  border: 1px solid var(--red-30);
  border-radius: var(--radius-10);
  color: var(--red);
  background: var(--surface-panel);
  text-align: center;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-8);
}
.storyboard-3d-runtime-status[hidden] {
  display: none;
}
.storyboard-3d-runtime-status span {
  max-width: 100%;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}
.storyboard-3d-runtime-status button {
  min-height: 32px;
  padding: 0 var(--space-12);
  border: 1px solid var(--red-30);
  border-radius: var(--radius-8);
  color: var(--text-strong);
  background: var(--bg-panel-card);
  cursor: var(--link-cursor);
}
.storyboard-3d-runtime-status button:hover {
  background: var(--blue-10);
}
.storyboard-3d-stage-kicker {
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.storyboard-3d-viewport-stage strong {
  color: var(--text-strong);
  font-size: clamp(18px, 2vw, 28px);
}
.storyboard-3d-viewport-stage p {
  max-width: 620px;
  margin: 0;
  color: var(--text-muted);
  line-height: 1.6;
}
.storyboard-3d-reuse-note {
  margin-top: var(--space-6);
  padding: var(--space-6) var(--space-10);
  border-radius: var(--radius-999);
  color: var(--green);
  background: var(--surface-panel);
  font-size: 11px;
}
.storyboard-3d-fit-all-control,
.storyboard-3d-focal-control,
.storyboard-3d-mini-map-placeholder,
.storyboard-3d-tool-rail,
.storyboard-3d-view-controls,
.storyboard-3d-viewport-hud,
.storyboard-3d-viewport-toolbar {
  --mini-map-window-x: 0px;
  --mini-map-window-y: 0px;
  position: absolute;
  z-index: 2;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  background: var(--surface-float);
  box-shadow: var(--shadow-toolbar);
  backdrop-filter: blur(10px);
}
.storyboard-3d-mini-map-placeholder.is-expanded {
  width: clamp(240px, 24vw, 320px);
  max-width: calc(100% - 28px);
}
.storyboard-3d-tool-rail {
  top: var(--space-14);
  left: var(--space-14);
  display: grid;
  justify-items: center;
  gap: var(--space-4);
  padding: var(--space-4);
}
.storyboard-3d-view-controls {
  top: var(--space-14);
  left: 50%;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-4);
  transform: translateX(-50%);
}
.storyboard-3d-viewport-toolbar {
  bottom: var(--space-14);
  left: 50%;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  max-width: min(620px, calc(100% - 112px));
  padding: var(--space-4);
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
  transform: translateX(-50%);
}
#v2-wrap .storyboard-3d-viewport-toolbar {
  scrollbar-width: none;
}
.storyboard-3d-viewport-toolbar::-webkit-scrollbar {
  display: none;
}
.storyboard-3d-viewport-toolbar [hidden] {
  display: none;
}
.storyboard-3d-icon-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  min-width: 36px;
  height: 36px;
  min-height: 36px;
  padding: 0;
  color: var(--text-secondary);
}
.storyboard-3d-icon-button:hover:not(:disabled) {
  color: var(--text-primary);
  background: var(--blue-10);
}
.storyboard-3d-icon-button:focus-visible {
  outline: 2px solid var(--blue-border-focus);
  outline-offset: 2px;
}
.storyboard-3d-control-icon {
  width: 18px;
  height: 18px;
}
.storyboard-3d-control-shortcut {
  position: absolute;
  right: 3px;
  bottom: 2px;
  max-width: calc(100% - 4px);
  color: var(--text-muted);
  font-size: 8px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  pointer-events: none;
}
.storyboard-3d-icon-button.is-active {
  color: var(--blue);
  background: var(--blue-10);
}
.storyboard-3d-icon-button.is-active .storyboard-3d-control-shortcut {
  color: var(--blue);
}
.storyboard-3d-transform-unavailable {
  margin: 0;
  padding: var(--space-8) var(--space-10);
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-8);
  color: var(--text-muted);
  background: var(--bg-panel-card);
  font-size: 10px;
  line-height: 1.5;
}
.storyboard-3d-tool-rail-separator {
  width: 22px;
  height: 1px;
  margin: var(--space-4) 0;
  background: var(--stroke-weak);
}
.storyboard-3d-view-controls-separator {
  width: 1px;
  height: 20px;
  margin: 0 var(--space-2);
  background: var(--stroke-weak);
}
.storyboard-3d-fit-all-control {
  position: absolute;
  right: var(--space-14);
  bottom: var(--space-14);
  z-index: 3;
}
.storyboard-3d-focal-control {
  right: var(--space-14);
  bottom: calc(var(--space-14) + 44px);
  display: grid;
  gap: var(--space-6);
  width: clamp(64px, 5vw, 76px);
  padding: var(--space-8) var(--space-6);
  color: var(--text-muted);
  font-size: 9px;
  cursor: default;
}
.storyboard-3d-focal-value {
  display: grid;
  justify-items: center;
  gap: 2px;
  white-space: nowrap;
}
.storyboard-3d-focal-value output {
  color: var(--text-primary);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-focal-slider-wrap {
  display: grid;
  grid-template-columns: 18px minmax(26px, 1fr);
  gap: var(--space-4);
  height: clamp(160px, 24vh, 216px);
  max-height: min(216px, calc(100vh - 280px));
  min-height: 120px;
}
.storyboard-3d-focal-slider-wrap input[type="range"] {
  width: 18px;
  height: 100%;
  min-height: 0;
  margin: 0;
  writing-mode: vertical-lr;
  direction: rtl;
  appearance: slider-vertical;
  color: var(--blue);
  accent-color: var(--blue);
  cursor: var(--resize-ns-cursor, ns-resize);
}
.storyboard-3d-focal-slider-wrap input[type="range"]:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.storyboard-3d-focal-ticks {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  height: 100%;
  min-height: 0;
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-focal-tick {
  position: relative;
  padding-left: var(--space-6);
  line-height: 1;
}
.storyboard-3d-focal-ticks button.storyboard-3d-focal-tick {
  appearance: none;
  padding-top: 0;
  padding-right: 0;
  padding-bottom: 0;
  border: 0;
  color: inherit;
  background: 0 0;
  font: inherit;
  text-align: left;
}
.storyboard-3d-focal-tick::before {
  position: absolute;
  top: 50%;
  left: 0;
  width: 4px;
  height: 1px;
  background: var(--stroke-strong);
  content: "";
}
.storyboard-3d-focal-tick.is-active {
  color: var(--blue);
  font-weight: 700;
}
.storyboard-3d-focal-tick.is-default {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: var(--text-secondary);
  white-space: nowrap;
  cursor: pointer;
}
.storyboard-3d-focal-tick.is-default::before {
  width: 7px;
  height: 2px;
  background: var(--blue);
}
.storyboard-3d-focal-tick.is-default small {
  color: var(--blue);
  font-size: 7px;
  font-weight: 700;
}
.storyboard-3d-focal-tick.is-default:focus-visible,
.storyboard-3d-focal-tick.is-default:hover {
  color: var(--blue);
}
.storyboard-3d-focal-tick.is-default:focus-visible {
  border-radius: var(--radius-4);
  outline: 1px solid var(--blue);
  outline-offset: 2px;
}
.storyboard-3d-object-popover {
  position: absolute;
  top: var(--space-14);
  left: calc(var(--space-14) + 48px);
  z-index: 3;
  width: clamp(300px, 30vw, 480px);
  max-width: calc(100% - 150px);
  max-height: calc(100% - 28px);
  overflow: hidden;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  background: var(--surface-float);
  box-shadow: var(--shadow-toolbar);
  backdrop-filter: blur(12px);
}
.storyboard-3d-object-popover:not([open]) {
  width: auto;
}
.storyboard-3d-object-popover > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-10);
  min-height: 38px;
  padding: 0 var(--space-10);
  color: var(--text-primary);
  cursor: var(--link-cursor);
  list-style: none;
}
.storyboard-3d-object-popover > summary::-webkit-details-marker {
  display: none;
}
.storyboard-3d-object-popover > summary::after {
  content: "+";
  color: var(--text-muted);
}
.storyboard-3d-object-popover[open] > summary::after {
  content: "−";
}
.storyboard-3d-object-popover > summary small {
  margin-left: auto;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-object-popover .storyboard-3d-object-outline {
  display: grid;
  grid-template-rows: auto auto auto auto;
  max-height: min(76vh, 760px);
  padding: 0 var(--space-10) var(--space-10);
  overflow: auto;
  border-top: 1px solid var(--stroke-weak);
  overscroll-behavior: contain;
}
.storyboard-3d-object-popover-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
  min-height: 40px;
  color: var(--text-muted);
  font-size: 10px;
}
.storyboard-3d-object-popover-heading button {
  min-height: 28px;
  padding: 0 var(--space-8);
}
.storyboard-3d-object-popover .storyboard-3d-outline-list {
  min-height: 0;
  max-height: min(30vh, 280px);
  margin-top: 0;
  overflow: auto;
  overscroll-behavior: contain;
}
.storyboard-3d-viewport-hud {
  bottom: calc(var(--space-14) + 48px);
  left: var(--space-14);
  display: flex;
  align-items: center;
  gap: var(--space-8);
  padding: var(--space-8) var(--space-10);
  font-size: 11px;
}
.storyboard-3d-viewport-hud .storyboard-3d-navigation-status {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-viewport-hud span {
  color: var(--text-muted);
}
.storyboard-3d-viewport-hud .storyboard-3d-navigation-status.is-fly-mode {
  color: var(--blue);
}
.storyboard-3d-mini-map-placeholder {
  top: var(--space-14);
  right: var(--space-14);
  display: grid;
