  gap: var(--space-6);
}
.storyboard-3d-shot-inspector-meta span,
.storyboard-3d-shot-inspector-meta strong {
  padding: 4px var(--space-6);
  border-radius: var(--radius-6);
  color: var(--text-secondary);
  background: var(--bg-panel-card);
  font-size: 10px;
}
.storyboard-3d-shot-inspector-actions button {
  flex: 1 1 52px;
}
.storyboard-3d-scene-control-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
  padding-top: var(--space-8);
  border-top: 1px solid var(--stroke-weak);
}
.storyboard-3d-viewport-settings {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-8);
  padding-top: var(--space-8);
  border-top: 1px solid var(--stroke-weak);
}
.storyboard-3d-viewport-settings label {
  display: grid;
  gap: 4px;
  color: var(--text-muted);
  font-size: 10px;
}
.storyboard-3d-viewport-settings label.is-check {
  display: flex;
  align-items: center;
  min-height: 30px;
  gap: var(--space-6);
}
.storyboard-3d-viewport-settings input:not([type="checkbox"]),
.storyboard-3d-viewport-settings select {
  width: 100%;
  min-width: 0;
  padding: 6px;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-6);
  color: var(--text-primary);
  background: var(--bg-panel-card);
  font: inherit;
  font-size: 10px;
}
.storyboard-3d-scene-control-actions small {
  color: var(--text-muted);
  text-align: right;
}
.storyboard-3d-ai-composer {
  overflow: visible;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-12);
  background: var(--surface-panel);
  box-shadow: var(--shadow-surface);
}
.storyboard-3d-ai-assistant {
  min-height: clamp(420px, 54vh, 720px);
  align-content: start;
}
.storyboard-3d-ai-feed {
  min-height: clamp(150px, 22vh, 300px);
  max-height: min(360px, 38vh);
  padding: var(--space-10);
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-10);
  background: var(--bg-panel-card);
}
.storyboard-3d-ai-message {
  display: grid;
  gap: var(--space-4);
  max-width: 92%;
  padding: var(--space-8) var(--space-10);
  border-radius: var(--radius-10);
  background: var(--surface-panel);
}
.storyboard-3d-ai-message span {
  color: var(--blue);
  font-size: 10px;
  font-weight: 600;
}
.storyboard-3d-ai-empty,
.storyboard-3d-ai-message p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.55;
}
.storyboard-3d-ai-empty {
  margin-top: var(--space-12);
  color: var(--text-muted);
}
.storyboard-3d-ai-prompt-wrap {
  padding: var(--space-10);
  border-bottom: 1px solid var(--stroke-default);
  border-radius: var(--radius-12) var(--radius-12) 0 0;
  background: var(--bg-panel-card);
}
.storyboard-3d-ai-prompt-wrap textarea {
  min-height: 108px;
  max-height: min(240px, 30vh);
  padding: 0;
  resize: vertical;
  border: 0;
  border-radius: 0;
  outline: 0;
  caret-color: var(--blue);
  background: 0 0;
  font-family: STSong, "Songti SC", serif;
  font-size: var(--font-13);
  line-height: 1.7;
}
.storyboard-3d-ai-prompt-wrap textarea:focus {
  border-color: transparent;
}
.storyboard-3d-ai-model-bar {
  display: grid;
  gap: var(--space-8);
  padding: var(--space-8);
}
.storyboard-3d-ai-model-bar .aigen-text-model-selector,
.storyboard-3d-ai-model-bar .img-model-btn-trigger,
.storyboard-3d-ai-model-bar .img-model-wrap {
  width: min(180px, 100%);
  min-width: 0;
  max-width: 100%;
}
.storyboard-3d-ai-model-bar .img-model-wrap {
  position: relative;
}
.storyboard-3d-ai-model-bar .img-model-btn-trigger {
  min-height: 36px;
  justify-content: flex-start;
  border-color: transparent;
  background: 0 0;
}
.storyboard-3d-ai-model-bar .img-model-btn-trigger:focus-visible,
.storyboard-3d-ai-model-bar .img-model-btn-trigger:hover {
  border-color: var(--stroke-strong);
  color: var(--text-primary);
  background: var(--fill-hover);
}
.storyboard-3d-ai-model-bar .img-model-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-ai-model-bar .img-model-menu {
  --model-menu-width: min(260px, calc(100vw - 40px));
}
.storyboard-3d-ai-assistant .node-model-submenu {
  right: calc(100% + 6px);
  left: auto;
}
.storyboard-3d-ai-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-6);
}
.storyboard-3d-ai-actions .is-primary {
  border-color: var(--blue);
  color: var(--text-on-icon-badge);
  background: var(--blue);
}
.storyboard-3d-ai-actions .is-primary:hover:not(:disabled) {
  border-color: var(--blue-border-strong);
  color: var(--text-on-icon-badge);
  background: var(--blue);
  box-shadow: 0 0 0 2px var(--blue-20);
}
.storyboard-3d-ai-transcript {
  margin: 0;
  color: var(--text-secondary);
  font-size: 10px;
}
.storyboard-3d-ai-plan {
  display: grid;
  gap: var(--space-4);
  max-height: min(180px, 24vh);
  margin: 0;
  padding: var(--space-6) var(--space-6) var(--space-6) 26px;
  overflow: auto;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-8);
  background: var(--bg-panel-card);
  font-size: 10px;
}
.storyboard-3d-ai-plan li span {
  display: block;
  overflow: hidden;
  color: var(--text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-ai-assistant[data-status="executing"],
.storyboard-3d-ai-assistant[data-status="listening"],
.storyboard-3d-ai-assistant[data-status="planning"] {
  border-color: var(--blue-30);
}
.storyboard-3d-export-main {
  display: grid;
  align-content: start;
  gap: var(--space-16);
  min-width: 0;
  min-height: 0;
  padding: clamp(16px, 2vw, 24px);
  overflow-y: auto;
}
.storyboard-3d-export-section,
.storyboard-3d-export-stage {
  display: grid;
  gap: var(--space-12);
}
.storyboard-3d-export-mode-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-10);
}
.storyboard-3d-export-inline-label {
  display: grid;
  min-width: 72px;
  gap: 2px;
}
.storyboard-3d-export-inline-label small {
  color: var(--blue);
  font-size: 9px;
  letter-spacing: 0.12em;
}
.storyboard-3d-export-inline-label strong {
  font-size: var(--font-12);
}
.storyboard-3d-export-mode-row > em {
  color: var(--text-muted);
  font-size: 10px;
  font-style: normal;
  white-space: nowrap;
}
.storyboard-3d-export-mode-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-8);
}
.storyboard-3d-export-choice {
  display: grid;
  align-content: center;
  gap: 3px;
  min-width: 0;
  min-height: 46px;
  padding: var(--space-6) var(--space-8);
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  color: var(--text-secondary);
  background: var(--bg-panel-card);
  text-align: left;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease;
}
.storyboard-3d-export-choice:focus-visible,
.storyboard-3d-export-choice:hover {
  transform: translateY(-1px);
  border-color: var(--stroke-strong);
  outline: 0;
}
.storyboard-3d-export-choice:active {
  transform: translateY(1px);
}
.storyboard-3d-export-choice.is-active {
  border-color: color-mix(in srgb, var(--blue) 64%, var(--stroke-default));
  color: var(--text-primary);
  background: color-mix(in srgb, var(--blue) 11%, var(--bg-panel-card));
  box-shadow: inset 0 0 0 1px var(--blue-10);
}
.storyboard-3d-export-choice strong {
  font-size: var(--font-11);
  font-weight: 600;
}
.storyboard-3d-export-choice small,
.storyboard-3d-export-grid-help,
.storyboard-3d-export-progress {
  color: var(--text-muted);
  font-size: 9px;
}
.storyboard-3d-export-settings {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-12);
}
.storyboard-3d-export-settings > div {
  display: grid;
  align-content: start;
  gap: var(--space-6);
  min-width: 0;
}
.storyboard-3d-export-settings > div > span {
  color: var(--text-muted);
  font-size: 10px;
}
.storyboard-3d-export-compact-options,
.storyboard-3d-export-grid-size-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: 4px;
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-10);
  background: var(--surface-panel);
}
.storyboard-3d-export-grid-size-options {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.storyboard-3d-export-compact-options .storyboard-3d-export-choice,
.storyboard-3d-export-grid-size-options .storyboard-3d-export-choice {
  min-height: 32px;
  padding: 5px 7px;
  border-color: transparent;
  border-radius: var(--radius-6);
  background: 0 0;
  text-align: center;
}
.storyboard-3d-export-compact-options .storyboard-3d-export-choice.is-active,
.storyboard-3d-export-grid-size-options .storyboard-3d-export-choice.is-active {
  border-color: var(--stroke-default);
  background: var(--fill-hover-strong);
  box-shadow: var(--shadow-surface);
}
.storyboard-3d-export-stage {
  padding: var(--space-14);
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-14);
  background:
    radial-gradient(circle at 70% 0, var(--blue-10), transparent 44%),
    var(--surface-panel);
}
.storyboard-3d-export-single-preview {
  display: grid;
  grid-template-columns: minmax(180px, 0.8fr) minmax(160px, 1fr);
  align-items: center;
  gap: var(--space-16);
  min-height: 170px;
}
.storyboard-3d-export-single-preview > .storyboard-3d-export-shot-placeholder,
.storyboard-3d-export-single-preview > img {
  width: 100%;
  aspect-ratio: 16/9;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
}
.storyboard-3d-export-single-preview > div {
  display: grid;
  gap: var(--space-4);
}
.storyboard-3d-export-single-preview > div strong {
  font-size: clamp(var(--font-18), 2vw, var(--font-24));
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-export-single-preview > div small {
  color: var(--text-muted);
}
.storyboard-3d-export-shot-placeholder {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  min-height: 52px;
  overflow: hidden;
  background-color: var(--bg);
  background-image:
    linear-gradient(var(--stroke-weak) 1px, transparent 1px),
    linear-gradient(90deg, var(--stroke-weak) 1px, transparent 1px);
  background-size: 14px 14px;
}
.storyboard-3d-export-shot-placeholder i {
  position: absolute;
  right: 12%;
  bottom: 10%;
  left: 12%;
  height: 38%;
  border: 1px solid var(--blue-20);
  transform: perspective(180px) rotateX(58deg);
}
.storyboard-3d-export-grid-composer {
  display: grid;
  gap: clamp(5px, 0.8vw, 10px);
  width: min(100%, 760px);
  margin: 0 auto;
  padding: clamp(8px, 1vw, 12px);
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-12);
  background: var(--bg);
}
.storyboard-3d-export-grid-composer[data-storyboard-3d-export-grid-size="4"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.storyboard-3d-export-grid-composer[data-storyboard-3d-export-grid-size="9"] {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.storyboard-3d-export-grid-composer[data-storyboard-3d-export-grid-size="16"] {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.storyboard-3d-export-grid-slot {
  position: relative;
  display: grid;
  min-width: 0;
  aspect-ratio: 16/9;
  overflow: hidden;
  border: 1px dashed var(--stroke-default);
  border-radius: var(--radius-8);
  background: var(--surface-panel);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}
.storyboard-3d-export-grid-slot.is-filled {
  border-style: solid;
  cursor: grab;
}
.storyboard-3d-export-grid-slot.is-drop-target {
  transform: scale(0.985);
  border-color: var(--blue);
  box-shadow:
    inset 0 0 0 2px var(--blue-20),
    0 0 0 1px var(--blue-30);
}
.storyboard-3d-export-grid-slot > .storyboard-3d-export-shot-placeholder,
.storyboard-3d-export-grid-slot > img {
  position: absolute;
  inset: 0;
}
.storyboard-3d-export-grid-empty,
.storyboard-3d-export-grid-slot
  > span:not(.storyboard-3d-export-shot-placeholder) {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  padding: 5px 7px;
  color: var(--text-secondary);
  background: linear-gradient(transparent, var(--black-80));
  font-size: 9px;
}
.storyboard-3d-export-grid-empty {
  top: 0;
  justify-content: center;
  background: 0 0;
}
.storyboard-3d-export-grid-empty b,
.storyboard-3d-export-grid-slot > span b {
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.storyboard-3d-export-grid-slot > span small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.storyboard-3d-export-grid-help {
  margin: 0;
  text-align: center;
}
.storyboard-3d-export-toggles {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-14);
  padding: var(--space-10) var(--space-12);
  border: 1px solid var(--stroke-weak);
  border-radius: var(--radius-10);
  background: var(--bg-panel-card);
}
.storyboard-3d-export-toggles label {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  color: var(--text-secondary);
  font-size: 10px;
}
.storyboard-3d-export-toggles input {
  accent-color: var(--blue);
}
.storyboard-3d-export-progress {
  min-height: 18px;
}
.storyboard-3d-export-form > footer {
  justify-content: flex-end;
  background: color-mix(in srgb, var(--bg-panel) 92%, transparent);
}
.storyboard-3d-export-form > footer button {
  min-width: 88px;
  min-height: 38px;
  padding: 0 var(--space-14);
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  color: var(--text-secondary);
  background: var(--surface-panel);
  font: inherit;
  font-size: var(--font-11);
  font-weight: 600;
  cursor: var(--link-cursor);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease;
}
.storyboard-3d-export-form > footer button:active:not(:disabled) {
  transform: translateY(1px);
}
.storyboard-3d-export-form > footer .is-primary {
  border-color: var(--blue);
  color: var(--text-on-icon-badge);
  background: var(--blue);
}
.storyboard-3d-export-form > footer .is-primary:focus-visible,
.storyboard-3d-export-form > footer .is-primary:hover:not(:disabled) {
  border-color: var(--blue-border-strong);
  color: var(--text-on-icon-badge);
  background: var(--blue);
  outline: 0;
  box-shadow: 0 0 0 2px var(--blue-20);
}
.storyboard-3d-export-destination-actions {
  display: grid;
  justify-items: end;
}
.storyboard-3d-export-destination-actions > div {
  display: flex;
  gap: var(--space-8);
}
.storyboard-3d-export-destination-actions > button[hidden],
.storyboard-3d-export-destination-actions > div[hidden] {
  display: none;
}
.storyboard-3d-export-destination-actions > div > button {
  min-width: 112px;
}
.storyboard-3d-export-form button:hover:not(:disabled) {
  border-color: var(--stroke-strong);
}
.storyboard-3d-export-trigger {
  border-color: color-mix(in srgb, var(--blue) 48%, var(--stroke-default));
  color: var(--text-primary);
  background: color-mix(in srgb, var(--blue) 10%, var(--surface-panel));
}
.storyboard-3d-editor-shell select {
  padding-right: 30px;
  appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--text-muted) 50%),
    linear-gradient(135deg, var(--text-muted) 50%, transparent 50%);
  background-position:
    calc(100% - 14px) 50%,
    calc(100% - 9px) 50%;
  background-repeat: no-repeat;
  background-size: 5px 5px;
}
.storyboard-3d-editor-shell select option {
  color: var(--text-primary);
  background: var(--surface-menu);
}
@media (max-width: 560px) {
  .storyboard-3d-export-dialog {
    padding: 0;
  }
  .storyboard-3d-export-form {
    width: 100vw;
    max-height: 100dvh;
    border-radius: 0;
  }
  .storyboard-3d-export-settings,
  .storyboard-3d-export-single-preview {
    grid-template-columns: 1fr;
  }
  .storyboard-3d-export-mode-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .storyboard-3d-export-mode-row {
    grid-template-columns: 1fr auto;
  }
  .storyboard-3d-export-mode-row .storyboard-3d-export-mode-options {
    grid-column: 1/-1;
    grid-row: 2;
  }
}
@media (max-width: 820px) {
  .storyboard-3d-export-layout {
    grid-template-columns: 1fr;
    overflow-y: auto;
  }
  .storyboard-3d-export-shot-rail {
    grid-template-rows: auto auto auto;
    border-right: 0;
    border-bottom: 1px solid var(--stroke-weak);
  }
  .storyboard-3d-export-shot-list {
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    max-height: min(30vh, 240px);
  }
  .storyboard-3d-export-shot-rail > p {
    display: none;
  }
}
@media (max-width: 820px) {
  .storyboard-3d-candidate-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
.storyboard-3d-editor-message {
  position: absolute;
  right: clamp(12px, 2vw, 24px);
  bottom: clamp(12px, 2vw, 24px);
  z-index: 8;
  max-width: min(460px, calc(100vw - 24px));
  padding: var(--space-10) var(--space-12);
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  color: var(--text-secondary);
  background: var(--surface-float);
  box-shadow: var(--shadow-popover);
}
@container storyboard-3d-right-sidebar (max-width:620px) {
  .storyboard-3d-asset-library-layout {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }
  .storyboard-3d-asset-library-sidebar {
    display: grid;
    max-height: min(42vh, 360px);
    padding: var(--space-12);
    border-right: 0;
    border-bottom: 1px solid var(--stroke-default);
    gap: var(--space-12);
  }
  .storyboard-3d-asset-sidebar-heading {
    display: none;
  }
  .storyboard-3d-asset-category-list {
    grid-auto-columns: max-content;
    grid-auto-flow: column;
    overflow-x: auto;
    overflow-y: hidden;
  }
  .storyboard-3d-asset-toolbar {
    margin: 0;
    padding: 0;
    border: 0;
  }
  .storyboard-3d-asset-toolbar small,
  .storyboard-3d-asset-toolbar > strong {
    display: none;
  }
}
@media (max-width: 1100px) {
  .storyboard-3d-topbar-actions button:not(.storyboard-3d-close-button) {
    padding-inline: var(--space-8);
    font-size: 11px;
  }
}
@media (max-width: 900px) {
  .storyboard-3d-editor-main,
  .storyboard-3d-editor-shell.is-inspector-open:not(.is-right-sidebar-open)
    .storyboard-3d-editor-main,
  .storyboard-3d-editor-shell.is-right-sidebar-open .storyboard-3d-editor-main {
    grid-template-columns: minmax(0, 1fr);
  }
  .storyboard-3d-editor-shell.is-inspector-open:not(.is-right-sidebar-open)
    .storyboard-3d-inspector-splitter,
  .storyboard-3d-inspector-splitter {
    display: none;
  }
  .storyboard-3d-inspector-dock {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    z-index: 6;
    width: min(360px, 88vw);
    transform: translateX(105%);
    box-shadow: var(--shadow-dialog);
    transition: transform 160ms ease;
  }
  .storyboard-3d-editor-shell.is-inspector-open .storyboard-3d-inspector-dock {
    display: block;
    transform: translateX(0);
  }
  .storyboard-3d-right-sidebar {
    position: absolute;
    top: 0;
    right: 0;
