.panel-resize-handle {
  position: relative;
  width: 14px;
  min-height: 72px;
  cursor: var(--resize-ew-cursor, ew-resize);
  outline: 0;
  border-radius: var(--radius-8);
  touch-action: none;
  user-select: none;
}
.panel-resize-handle::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: var(--side-panel-border);
  transform: translateX(-50%);
}
.panel-resize-handle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 3px;
  height: 44px;
  border-radius: 999px;
  background: var(--white-20);
  transform: translate(-50%, -50%);
  transition:
    background 0.16s ease,
    height 0.16s ease,
    opacity 0.16s ease,
    width 0.16s ease;
}
.panel-resize-handle--horizontal {
  width: 100%;
  height: 14px;
  min-height: 0;
  cursor: var(--resize-ns-cursor, ns-resize);
}
#v2-wrap .panel-resize-handle {
  cursor: var(--resize-ew-cursor, ew-resize);
}
#v2-wrap .panel-resize-handle--horizontal {
  cursor: var(--resize-ns-cursor, ns-resize);
}
.panel-resize-handle--horizontal::before {
  top: 50%;
  right: 0;
  bottom: auto;
  left: 0;
  width: auto;
  height: 1px;
  transform: translateY(-50%);
}
.panel-resize-handle--horizontal::after {
  width: 44px;
  height: 3px;
}
.panel-resize-handle--transient::after,
.panel-resize-handle--transient::before {
  opacity: 0;
}
.panel-resize-handle.is-active::after,
.panel-resize-handle:focus-visible::after,
.panel-resize-handle:hover::after,
body.audio-voice-panel-resizing .panel-resize-handle::after,
body.story-assets-resizing .panel-resize-handle::after,
body.story-episode-resizing .panel-resize-handle::after {
  background: var(--blue);
}
.panel-resize-handle--transient.is-active::after,
.panel-resize-handle--transient:focus-visible::after,
.panel-resize-handle--transient:hover::after,
body.story-assets-resizing .panel-resize-handle--transient::after,
body.story-episode-resizing .panel-resize-handle--transient::after {
  opacity: 1;
}
.panel-resize-handle:not(.panel-resize-handle--horizontal).is-active::after,
.panel-resize-handle:not(.panel-resize-handle--horizontal):focus-visible::after,
.panel-resize-handle:not(.panel-resize-handle--horizontal):hover::after,
body.audio-voice-panel-resizing
  .panel-resize-handle:not(.panel-resize-handle--horizontal)::after,
body.story-assets-resizing
  .panel-resize-handle:not(.panel-resize-handle--horizontal)::after,
body.story-episode-resizing
  .panel-resize-handle:not(.panel-resize-handle--horizontal)::after {
  height: 72px;
}
.panel-resize-handle--horizontal.is-active::after,
.panel-resize-handle--horizontal:focus-visible::after,
.panel-resize-handle--horizontal:hover::after {
  width: 72px;
}
@media (prefers-reduced-motion: reduce) {
  .panel-resize-handle::after {
    transition: none;
  }
}
body {
  --audio-voice-panel-width: var(
    --agent-sidebar-width,
    min(clamp(560px, 38vw, 860px), calc(100vw - 24px))
  );
}
.audio-voice-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 1001;
  display: flex;
  width: var(--audio-voice-panel-width);
  flex-direction: column;
  overflow: visible;
  border-left: 1px solid var(--side-panel-border);
  background: var(--side-panel-bg);
  color: var(--text-primary);
  box-shadow: var(--side-panel-shadow);
  opacity: 0;
  pointer-events: none;
  transform: translateX(100%);
  transition:
    transform 0.34s cubic-bezier(0.2, 0, 0.2, 1),
    opacity 0.22s ease;
}
.audio-voice-panel.is-open {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
}
.audio-voice-pick-notice {
  position: fixed;
  top: calc(var(--header-h, 56px) + var(--space-14));
  left: calc((100vw - var(--audio-voice-panel-width)) / 2);
  z-index: 94;
  max-width: min(
    420px,
    max(220px, calc(100vw - var(--audio-voice-panel-width) - 48px))
  );
  padding: 8px 14px;
  border: 1px solid var(--blue-border-focus);
  border-radius: 8px;
  background: var(--side-panel-menu-bg);
  box-shadow: var(--side-panel-shadow);
  color: var(--text-primary);
  font-size: var(--font-13);
  font-weight: 800;
  line-height: 1.4;
  pointer-events: none;
  text-align: center;
  transform: translateX(-50%);
}
