  overflow-y: auto;
  resize: vertical;
  scrollbar-width: thin;
}
.story-chapter-content textarea {
  align-self: start;
  min-height: clamp(110px, 15vh, 190px);
  padding: 12px;
  resize: vertical;
}
.story-chapter-content textarea:focus,
.story-chapter-title input:focus,
.story-outline-field input:focus,
