  background: var(--story-contrast-action-bg);
  color: var(--story-contrast-action-text);
}
.story-page-footer .story-script-continue-button {
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
  padding: 0;
}
.story-script-continue-button svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
}
.story-next-arrow {
  font-size: var(--font-18);
  line-height: 1;
  transition: transform 160ms ease;
}
.story-page-footer .story-next-button:hover .story-next-arrow {
  transform: translateX(3px);
}
.story-assets-layout {
  display: grid;
  grid-template-columns: minmax(
      280px,
      var(--story-assets-left, 50%)
    ) 18px minmax(340px, 1fr);
  flex: 1 1 auto;
  gap: 0;
  min-height: 0;
  align-items: stretch;
  overflow: visible;
}
.story-assets-page.story-content-page {
  display: flex;
  width: calc(100vw - clamp(24px, 2.4vw, 48px));
  height: 100%;
  min-height: 0;
  flex-direction: column;
  padding: clamp(18px, 2.6vh, 30px) 0 clamp(104px, 13vh, 146px);
}
.story-assets-page .story-page-heading {
  align-items: center;
  justify-content: flex-start;
  margin-bottom: 16px;
}
.story-assets-splitter {
