  border-radius: 16px;
  background: var(--story-accent-soft);
}
.story-assets-callout div {
  display: grid;
  gap: 4px;
}
.story-assets-callout > div:first-child {
  flex: 1 1 180px;
  min-width: min(100%, 180px);
}
.story-assets-callout .story-assets-callout-actions {
  display: flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  grid-auto-flow: column;
  align-items: center;
