  gap: 8px;
  flex-shrink: 0;
}
.story-assets-callout .story-asset-batch-menu-wrap {
  display: flex;
  align-items: center;
  gap: 0;
  min-width: 0;
}
.story-library-add-menu-wrap {
  position: relative;
}
.story-assets-callout .story-asset-batch-trigger {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: 0 0;
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    border-color 180ms ease,
    color 180ms ease;
}
.story-assets-callout .story-asset-batch-trigger::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background: var(--story-action-bg);
  transform: none;
  transition: transform 180ms cubic-bezier(0.22, 0.72, 0.2, 1);
}
.story-asset-batch-trigger-label {
  position: relative;
  z-index: 1;
}
.story-assets-callout
  .story-asset-batch-menu-wrap.is-open
  .story-asset-batch-trigger {
  border-color: var(--story-line);
  color: var(--story-text);
}
.story-assets-callout
  .story-asset-batch-menu-wrap.is-open
  .story-asset-batch-trigger::before {
  transform: translateX(105%);
}
.story-assets-callout .story-asset-batch-menu {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 4px;
  max-width: 0;
  min-width: 0;
  margin-left: 0;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(-6px);
  transition:
    max-width 220ms cubic-bezier(0.22, 0.72, 0.2, 1),
    margin-left 220ms cubic-bezier(0.22, 0.72, 0.2, 1),
    opacity 120ms ease,
    transform 180ms cubic-bezier(0.22, 0.72, 0.2, 1),
    visibility 120ms ease;
}
.story-assets-callout .story-asset-batch-menu::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: 999px;
  background: var(--story-action-bg);
  opacity: 0;
  transform: translateX(-105%);
  transition:
    opacity 0.1s ease,
    transform 0.2s cubic-bezier(0.22, 0.72, 0.2, 1);
}
.story-assets-callout
  .story-asset-batch-menu-wrap.is-open
  .story-asset-batch-menu {
  max-width: min(var(--workspace-inline-menu-expanded-width, 246px), 42vw);
  margin-left: 8px;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: none;
}
.story-asset-batch-menu button {
  position: relative;
  z-index: 1;
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 5px;
  min-height: 34px;
  padding: 7px 9px;
  border: 1px solid var(--story-line);
  border-radius: 999px;
  background: var(--story-surface-subtle);
  color: var(--story-text);
  white-space: nowrap;
  cursor: var(--link-cursor);
  opacity: 0;
  transform: translateX(-6px);
  transition:
    opacity 120ms ease,
    transform 180ms cubic-bezier(0.22, 0.72, 0.2, 1),
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease;
}
.story-asset-batch-menu-wrap.is-open .story-asset-batch-menu button {
  border-color: color-mix(in srgb, var(--story-action-text) 14%, transparent);
  background: color-mix(in srgb, var(--story-action-text) 8%, transparent);
  color: var(--text-secondary);
  opacity: 1;
  transform: none;
}
.story-assets-callout
  .story-asset-batch-menu-wrap.is-open
  .story-asset-batch-menu::before {
  opacity: 1;
  transform: none;
}
.story-asset-batch-menu-wrap.is-open
  .story-asset-batch-menu
  button:nth-child(2) {
  transition-delay: 40ms, 40ms, 0s, 0s, 0s;
}
.story-asset-batch-menu-wrap.is-open
  .story-asset-batch-menu
  button:nth-child(3) {
  transition-delay: 60ms, 60ms, 0s, 0s, 0s;
}
.story-asset-batch-menu button:focus-visible,
.story-asset-batch-menu button:hover {
  outline: 0;
  border-color: var(--stroke-strong);
  background: var(--fill-hover-strong);
}
.story-asset-batch-menu-wrap.is-open
  .story-asset-batch-menu
  button:focus-visible,
.story-asset-batch-menu-wrap.is-open .story-asset-batch-menu button:hover {
  border-color: color-mix(in srgb, var(--story-action-text) 30%, transparent);
  background: color-mix(in srgb, var(--story-action-text) 18%, transparent);
  color: var(--story-action-text);
}
.story-asset-batch-menu-wrap.is-open .story-asset-batch-menu button.is-active {
  border-color: color-mix(in srgb, var(--story-action-text) 42%, transparent);
