  width: 16px;
  height: 16px;
}
.story-asset-batch-mode-icon svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 1.55;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.story-assets-callout p,
.story-page-description {
