  }
  .person-replacement-person-panel {
    grid-column: 1/-1;
    min-height: min(48vh, 460px);
    border-top: 1px solid var(--person-replacement-line);
    border-left: 0;
  }
  .person-replacement-analysis-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-height: none;
  }
