    display: none;
  }
  .person-replacement-step {
    justify-content: center;
    padding-inline: var(--space-8);
  }
  .person-replacement-feature-grid,
  .person-replacement-generation-sidebar {
    grid-template-columns: minmax(0, 1fr);
  }
  .person-replacement-source-summary {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }
  .person-replacement-source-stats {
    grid-column: 2/-1;
    justify-content: flex-start;
  }
  .person-replacement-review-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .person-replacement-review-panel + .person-replacement-review-panel {
    border-top: 1px solid var(--person-replacement-line);
    border-left: 0;
  }
  .person-replacement-shot-list-panel {
    max-height: min(36vh, 300px);
