  background: var(--side-panel-hover-bg);
}
.node-manager-row.is-dragging {
  opacity: 0.55;
}
.node-manager-row.is-busy .node-manager-row-main {
  opacity: 0.58;
}
.node-manager-group-chevron,
.node-manager-group-chevron-spacer {
  width: 20px;
  height: 42px;
}
.node-manager-group-chevron {
  border-radius: var(--radius-8);
  color: var(--text-subtle);
}
.node-manager-group-chevron svg {
  width: 18px;
  height: 18px;
  transition: transform 0.15s ease;
}
.node-manager-group-chevron.is-open svg {
  transform: rotate(90deg);
}
.node-manager-row.is-group[aria-expanded="true"] .node-manager-group-chevron {
  color: var(--text-primary);
}
.node-manager-row-main {
  display: flex;
  min-width: 0;
  height: 48px;
  align-items: center;
  gap: var(--space-10);
  padding: var(--space-4);
  border-radius: var(--radius-10);
  background: 0 0;
  text-align: left;
  cursor: var(--grab-cursor);
}
.node-manager-row.is-group .node-manager-row-main {
  height: 42px;
  gap: var(--space-6);
  padding-block: var(--space-4);
  cursor: var(--link-cursor);
}
.node-manager-row-main:active:not(:disabled) {
  cursor: var(--grabbing-cursor);
}
.node-manager-thumb {
  position: relative;
  display: inline-flex;
  width: clamp(38px, 2.6vw, 44px);
  height: clamp(38px, 2.6vw, 44px);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid var(--stroke-default);
  border-radius: var(--radius-10);
  background: var(--fill-hover);
  color: var(--text-secondary);
}
.node-manager-thumb.is-text {
  background: var(--icon-text-bg);
}
.node-manager-thumb.is-audio {
  background: var(--icon-audio-bg);
}
.node-manager-thumb.is-video {
  background: var(--icon-video-bg);
}
.node-manager-thumb-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.node-manager-thumb-fallback-icon {
  width: 19px;
  height: 19px;
}
.node-manager-folder-icon {
  width: 28px;
  height: 24px;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: 0 0;
  color: var(--text-secondary);
  filter: drop-shadow(0 4px 8px var(--black-30));
}
.node-manager-folder-icon svg {
  width: 100%;
  height: 100%;
}
.node-manager-folder-icon .is-open {
  display: none;
}
.node-manager-row.is-group[aria-expanded="true"]
  .node-manager-folder-icon
  .is-closed {
  display: none;
}
.node-manager-row.is-group[aria-expanded="true"]
  .node-manager-folder-icon
  .is-open {
  display: block;
}
.node-manager-video-badge {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-on-icon-badge);
  background: var(--black-25);
}
.node-manager-video-badge svg {
  width: 16px;
  height: 16px;
}
.node-manager-row-name {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  font-size: var(--font-14);
  font-weight: 550;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.node-manager-row.is-group .node-manager-row-name {
  color: var(--text-subtle);
  font-weight: 700;
  transition: color 0.15s ease;
}
.node-manager-row.is-group[aria-expanded="true"] .node-manager-row-name {
  color: var(--text-primary);
}
.node-manager-group-count {
  flex: 0 0 auto;
  color: var(--text-muted);
  font-size: var(--font-11);
  white-space: nowrap;
}
.node-manager-row-rename {
  width: 100%;
  padding: var(--space-6) var(--space-8);
  font-size: var(--font-13);
}
.node-manager-more-button {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-10);
  opacity: 0;
  transition: opacity 0.12s ease;
}
.node-manager-row.is-selected .node-manager-more-button,
.node-manager-row:focus-within .node-manager-more-button,
.node-manager-row:hover .node-manager-more-button {
  opacity: 1;
}
.node-manager-more-icon {
  width: 18px;
  height: 18px;
}
.node-manager-row-spinner {
  position: absolute;
  right: var(--space-10);
}
.node-manager-empty {
  display: flex;
  min-height: 120px;
  align-items: center;
  justify-content: center;
  padding: var(--space-20);
  color: var(--text-muted);
  font-size: var(--font-13);
  text-align: center;
}
.node-manager-footer {
  display: flex;
  min-height: 48px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-12);
  padding: var(--space-8) var(--space-12);
  border-top: 1px solid var(--stroke-default);
}
.node-manager-collapse-button {
  display: inline-flex;
  min-width: 0;
  height: 32px;
  align-items: center;
  gap: var(--space-6);
  padding: 0 var(--space-8);
  border-radius: var(--radius-8);
  background: 0 0;
  color: var(--text-secondary);
  cursor: var(--link-cursor);
}
.node-manager-collapse-button:hover {
  background: var(--fill-hover);
  color: var(--text-primary);
}
.node-manager-collapse-icon {
  width: 17px;
  height: 17px;
}
.node-manager-panel[data-placement="right"] .node-manager-collapse-icon {
  transform: scaleX(-1);
}
.node-manager-panel[data-placement="bottom"] .node-manager-collapse-icon {
  transform: rotate(-90deg);
}
.node-manager-collapse-label,
.node-manager-total {
  font-size: var(--font-12);
  white-space: nowrap;
}
.node-manager-total {
  color: var(--text-muted);
}
#v2-wrap.left-sidebar-auto-hide.node-manager-open
  .left-sidebar-hover-zone::after {
  opacity: 0;
  transform: translateY(-50%) scaleY(0.82);
}
#v2-wrap.left-sidebar-auto-hide.node-manager-open .sidebar-floating {
  opacity: 1;
  background: var(--surface-node);
  border-color: var(--stroke-default);
  box-shadow: var(--shadow-menu);
  transform: translateY(-50%);
  pointer-events: auto;
  transition-delay: 0s;
}
#v2-wrap.left-sidebar-auto-hide.node-manager-open .sidebar-floating::before {
  opacity: 0;
  transform: translateY(-50%) scaleY(0.82);
}
#v2-wrap.left-sidebar-auto-hide.node-manager-open .sidebar-floating > * {
  opacity: 1;
  transform: translate(0);
  pointer-events: auto;
}
#v2-wrap.canvas-toolbar-bottom.left-sidebar-auto-hide.node-manager-open
  .sidebar-floating {
  transform: translateX(-50%);
}
@media (max-width: 720px) {
  #v2-wrap {
    --node-manager-bottom-height: min(
      calc(
        48px + 48px + 40px + 6px + var(--node-manager-bottom-card-height) +
          var(--space-8)
      ),
      calc(100dvh - var(--header-h) - var(--space-12))
    );
  }
  .node-manager-panel {
    --node-manager-side-width: min(296px, 100vw);
  }
  .node-manager-panel[data-placement="left"],
  .node-manager-panel[data-placement="right"] {
    top: max(calc(var(--header-h) + var(--space-8)), var(--space-10));
    bottom: var(--space-10);
    width: var(--node-manager-side-width);
  }
  #v2-wrap.canvas-toolbar-bottom .node-manager-panel[data-placement="left"],
  .node-manager-panel[data-placement="left"] {
    left: 0;
  }
  .node-manager-panel[data-placement="right"] {
    right: 0;
  }
  .node-manager-panel[data-placement="bottom"] {
    width: 100vw;
    height: var(--node-manager-bottom-height);
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: 48px 48px minmax(0, 1fr) 40px;
  }
  .node-manager-panel[data-placement="bottom"] > .node-manager-project-row {
    grid-column: 1;
    grid-row: 1;
    min-height: 48px;
    border-right: 0;
  }
  .node-manager-panel[data-placement="bottom"] > .node-manager-controls {
    grid-column: 1;
    grid-row: 2;
    min-height: 48px;
  }
  .node-manager-panel[data-placement="bottom"] > .node-manager-list {
    grid-column: 1;
    grid-row: 3;
  }
  .node-manager-panel[data-placement="bottom"] > .node-manager-footer {
    grid-column: 1;
    grid-row: 4;
  }
  .node-manager-collapse-label {
    display: none;
  }
}
@media (min-width: 2200px) {
  .node-manager-panel {
    --node-manager-side-width: clamp(320px, 10vw, 384px);
  }
  .node-manager-panel[data-placement="bottom"] {
    width: 100vw;
    height: var(--node-manager-bottom-height);
  }
  .node-manager-row {
    min-height: 58px;
  }
  .node-manager-row-main {
    height: 54px;
  }
}
@media (hover: none) {
  .node-manager-more-button {
    opacity: 0.72;
  }
}
@media (prefers-reduced-motion: reduce) {
  .node-manager-group-chevron svg,
  .node-manager-group-toggle-icon,
  .node-manager-more-button,
  .node-manager-panel,
  .node-manager-row,
  .node-manager-row-name {
    transition: none;
  }
}
